test("withdrawn lecture history remains unavailable to staff and allocated learners while evidence is retained", async (t) => {
  const {sqlite, repository} = harness();
  t.after(() => sqlite.close());
  await publishFlow(repository);
  sqlite.prepare("INSERT INTO enrolments VALUES ('course-1',?,'active')").run(LEARNER.userId);
  sqlite.prepare("INSERT INTO workbook_assignments VALUES ('withdrawal-assignment',?,?,'active')").run(WORKBOOK_ID, LEARNER.userId);
  assert.equal((await repository.getPublishedLecture(LEARNER, WORKBOOK_ID)).manifest.workbook.id, WORKBOOK_ID);
  const preserved = sqlite.prepare("SELECT manifest_json,integrity_hash,version FROM lecture_versions WHERE workbook_id=?").get(WORKBOOK_ID);
  sqlite.prepare("UPDATE workbooks SET status='withdrawn' WHERE id=?").run(WORKBOOK_ID);
  await assert.rejects(() => repository.getPublishedLecture(AUTHOR, WORKBOOK_ID), (error: any) => error.status === 404);
  await assert.rejects(() => repository.getPublishedLecture(LEARNER, WORKBOOK_ID), (error: any) => error.status === 403);
  assert.deepEqual(sqlite.prepare("SELECT manifest_json,integrity_hash,version FROM lecture_versions WHERE workbook_id=?").get(WORKBOOK_ID), preserved);
});

